   var sp=SecureXml.parse(fixture).getDocumentElement();require(MD.equals(sp.getNamespaceURI())&&"EntityDescriptor".equals(sp.getLocalName())&&entity.equals(sp.getAttribute("entityID")));var peerKeys=MetadataAlgorithmEvidence.signingKeys(sp);require(!peerKeys.isEmpty()&&signed(sp,peerKeys));
