   var refs=new ArrayList<EvidenceRef>();for(var e:List.of(fetch,prepared,negative,request,response))refs.add(new EvidenceRef("transcript",e.id()));refs.add(new EvidenceRef("native-shibboleth-subject-confirmation",context.runId()+SUFFIX+".json#"+hash(manifestRaw)));
